-- =============================================================================
-- CineROI AI — mock seed data (Requirement 17.7)
-- =============================================================================
--
-- GENERATED FILE — do not edit by hand. Regenerate with:
--     python database/seed/generate_seed_sql.py
--
-- Prerequisite: the Alembic schema must exist (alembic upgrade head) and
-- 01_schema.sql must have created subscriber_clusters. Running seed.py does
-- both for you. This script is idempotent via ON CONFLICT DO NOTHING on the
-- deterministic primary keys below.
--
-- Transaction boundaries are owned by the caller (seed.py wraps the whole
-- script in a single transaction), so this file intentionally emits NO
-- BEGIN/COMMIT of its own — an inner COMMIT would close the caller's
-- transaction early and break container-startup initialization (R18.4).
-- =============================================================================

-- Users: exactly one per User_Role (R20.1).
ON CONFLICT (user_id) DO NOTHING;

-- Initial ACTIVE model version; coupled weights sum to exactly 1.00 (R12.2, R26.1).
ON CONFLICT (model_version_id) DO NOTHING;

-- Dated USD normalization rates (R21.4).
ON CONFLICT (from_currency, to_currency, rate_date) DO NOTHING;

-- Market telemetry per (genre_tag, territory) pair (R13.2, R13.3). These
-- drive territory-weighted CPM/LTV in the Guardrails engine (R21.3); the
-- seeded title_versions back-fill divides out these weights so the stored
-- scorecards stay identical under a live recompute.
ON CONFLICT (genre_tag, territory) DO NOTHING;

-- Candidate titles spanning every asset_type (R17.4). deal_stage seeds
-- the acquisition pipeline across a realistic mix of lifecycle stages.
ON CONFLICT (title_id) DO NOTHING;

-- One active title_version per title (R24.2, R24.4).
-- source_snapshot is an encrypted-at-rest TEXT column (R28.1). The seed
-- loads plaintext JSON (readable only with CINEROI_ENCRYPTION_REQUIRED=false,
-- the local/dev passthrough); a production load would supply ciphertext.
ON CONFLICT (title_version_id) DO NOTHING;

